+
+        public String getInEncoding ()
+        {
+            return m_inEncoding;
+        }
+        
+        public void setOutEncoding (final String outEncoding)
+        {
+            if ($assert.ENABLED) $assert.ASSERT (outEncoding != null, "null input: outEncoding");
