-        final HTMLDocument page = new HTMLDocument (title, m_settings.getOutputEncoding ());
+        final HTMLDocument page = new HTMLDocument (title, m_settings.getOutEncoding ());
         page.addStyle (CSS); // TODO: split by visit type

         return page;
